// Secure Express application with proper error handling and input validation

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const sanitizeHtml = require('sanitize-html');
const winston = require('winston');

const app = express();

// Environment configuration
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Logger configuration
const logger = winston.createLogger({
  level: NODE_ENV === 'production' ? 'info' : 'debug',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
    new winston.transports.Console({
      format: winston.format.simple()
    })
  ],
});

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn(`Rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({
      error: 'Too many requests',
      message: 'Please try again later',
      retryAfter: Math.ceil(limiter.windowMs / 1000)
    });
  }
});
app.use(limiter);

// Body parsing middleware
app.use(express.json({ limit: '10kb' })); // Limit body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request sanitization middleware
const sanitizeInput = (input) => {
  if (typeof input === 'string') {
    return sanitizeHtml(input, {
      allowedTags: [],
      allowedAttributes: {},
      allowedSchemes: [],
    });
  }
  return input;
};

app.use((req, res, next) => {
  // Sanitize query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      req.query[key] = sanitizeInput(req.query[key]);
    });
  }

  // Sanitize body
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      req.body[key] = sanitizeInput(req.body[key]);
    });
  }

  next();
});

// Request logging middleware
app.use((req, res, next) => {
  logger.info(`${req.method} ${req.url} - ${req.ip}`, {
    method: req.method,
    url: req.url,
    ip: req.ip,
    userAgent: req.get('User-Agent')
  });
  next();
});

// Validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation failed', { errors: errors.array() });
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
        location: err.location
      }))
    });
  }
  next();
};

// Health check endpoint - with optional query parameter validation
app.get('/health', 
  query('format').optional().isIn(['json', 'xml']).withMessage('Format must be json or xml'),
  validateRequest,
  (req, res) => {
    try {
      const healthData = {
        status: 'ok',
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        environment: NODE_ENV
      };

      // Check for system health issues
      if (healthData.uptime < 0) {
        throw new Error('Invalid uptime detected');
      }

      res.json(healthData);
    } catch (error) {
      logger.error('Health check error:', error);
      res.status(500).json({
        error: 'Health check failed',
        message: NODE_ENV === 'development' ? error.message : 'Internal server error'
      });
    }
  }
);

// Users endpoint - with pagination and filtering
app.get('/users',
  [
    query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    query('search').optional().isLength({ max: 50 }).withMessage('Search term too long')
  ],
  validateRequest,
  (req, res) => {
    try {
      const page = parseInt(req.query.page) || 1;
      const limit = parseInt(req.query.limit) || 10;
      const search = req.query.search;

      // Mock users data (in real app, fetch from database)
      let users = [
        { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
        { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
      ];

      // Apply search filter
      if (search) {
        users = users.filter(user => 
          user.name.toLowerCase().includes(search.toLowerCase())
        );
      }

      // Apply pagination
      const startIndex = (page - 1) * limit;
      const endIndex = page * limit;
      const paginatedUsers = users.slice(startIndex, endIndex);

      // Don't expose sensitive data in response
      const sanitizedUsers = paginatedUsers.map(user => ({
        id: user.id,
        name: user.name,
        // Only expose email if authorized (in real app, check authentication)
        email: req.isAuthenticated ? user.email : undefined,
        role: user.role
      }));

      res.json({
        data: sanitizedUsers,
        pagination: {
          page,
          limit,
          total: users.length,
          totalPages: Math.ceil(users.length / limit)
        }
      });
    } catch (error) {
      logger.error('Users endpoint error:', error);
      res.status(500).json({
        error: 'Failed to fetch users',
        message: NODE_ENV === 'development' ? error.message : 'Internal server error'
      });
    }
  }
);

// Example POST endpoint with validation
app.post('/users',
  [
    body('name').trim().isLength({ min: 2, max: 50 }).withMessage('Name must be 2-50 characters'),
    body('email').isEmail().normalizeEmail().withMessage('Valid email required'),
    body('role').optional().isIn(['user', 'admin']).withMessage('Invalid role')
  ],
  validateRequest,
  (req, res) => {
    try {
      // In real app, save to database
      const newUser = {
        id: Date.now(), // In production, use proper ID generation
        name: req.body.name,
        email: req.body.email,
        role: req.body.role || 'user'
      };

      logger.info('New user created', { userId: newUser.id });

      res.status(201).json({
        message: 'User created successfully',
        data: {
          id: newUser.id,
          name: newUser.name,
          role: newUser.role
          // Don't return email in response for security
        }
      });
    } catch (error) {
      logger.error('Create user error:', error);
      res.status(500).json({
        error: 'Failed to create user',
        message: NODE_ENV === 'development' ? error.message : 'Internal server error'
      });
    }
  }
);

// 404 handler for unknown routes
app.use((req, res) => {
  logger.warn(`404 - Route not found: ${req.method} ${req.url}`);
  res.status(404).json({
    error: 'Not found',
    message: 'The requested resource does not exist',
    path: req.url
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  logger.error('Unhandled error:', {
    error: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method
  });

  // Don't expose stack traces in production
  res.status(err.status || 500).json({
    error: 'Internal server error',
    message: NODE_ENV === 'development' ? err.message : 'Something went wrong',
    ...(NODE_ENV === 'development' && { stack: err.stack })
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully');
  process.exit(0);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', error);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

// Start server
if (require.main === module) {
  app.listen(PORT, () => {
    logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

