const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ====================
// SECURITY MIDDLEWARE
// ====================

// Security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"], // Allow inline styles if needed
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  hidePoweredBy: true, // Hide X-Powered-By header
  noSniff: true, // Prevent MIME sniffing
  frameguard: { action: 'deny' } // Prevent clickjacking
}));

// CORS configuration - adjust origins based on your needs
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Rate limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  handler: (req, res) => {
    res.status(429).json({
      error: 'Rate limit exceeded',
      message: 'Too many requests from this IP address'
    });
  }
});
app.use('/api/', apiLimiter); // Apply rate limiting to API routes

// Body parser with size limit
app.use(express.json({ limit: '10kb' })); // Limit body size to prevent payload abuse
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Custom input sanitization middleware
const sanitizeInput = (req, res, next) => {
  // Sanitize request parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = req.query[key].trim();
      }
    });
  }

  if (req.body) {
    Object.keys(req.body).forEach(key => {
      if (typeof req.body[key] === 'string') {
        req.body[key] = req.body[key].trim();
      }
    });
  }

  next();
};

// ====================
// VALIDATION MIDDLEWARE
// ====================

// Generic validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

// User validation rules
const userValidation = [
  query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('search').optional().isLength({ max: 50 }).withMessage('Search query too long')
];

// ====================
// ROUTES
// ====================

// Health check - no validation needed
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      error: 'Health check failed',
      message: error.message 
    });
  }
});

// Users endpoint with validation
app.get('/api/users', 
  userValidation,
  validateRequest,
  sanitizeInput,
  (req, res, next) => {
    try {
      // Extract validated query parameters
      const page = parseInt(req.query.page) || 1;
      const limit = parseInt(req.query.limit) || 10;
      const search = req.query.search?.toLowerCase();

      // Mock user data (in real app, this would come from database)
      let users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply search filter if provided
      if (search) {
        users = users.filter(user => 
          user.name.toLowerCase().includes(search) ||
          user.email.toLowerCase().includes(search)
        );
      }

      // Apply pagination
      const startIndex = (page - 1) * limit;
      const endIndex = startIndex + limit;
      const paginatedUsers = users.slice(startIndex, endIndex);

      res.status(200).json({
        data: paginatedUsers,
        pagination: {
          page,
          limit,
          total: users.length,
          hasMore: endIndex < users.length
        }
      });
    } catch (error) {
      next(error); // Pass to error handler
    }
  }
);

// Create user endpoint (example of POST with validation)
app.post('/api/users', 
  sanitizeInput,
  [
    body('name').trim().isLength({ min: 2, max: 50 }).withMessage('Name must be 2-50 characters'),
    body('email').isEmail().normalizeEmail().withMessage('Valid email is required'),
    body('age').optional().isInt({ min: 0, max: 120 }).withMessage('Age must be a valid number')
  ],
  validateRequest,
  (req, res, next) => {
    try {
      const { name, email, age } = req.body;

      // In real app, check if user already exists
      // Check for existing email
      if (isEmailTaken(email)) {
        return res.status(409).json({ 
          error: 'Email already exists' 
        });
      }

      const newUser = {
        id: Date.now(), // Simple ID generation
        name,
        email,
        age: age || null
      };

      res.status(201).json({
        message: 'User created successfully',
        data: newUser
      });
    } catch (error) {
      next(error);
    }
  }
);

// ====================
// ERROR HANDLING
// ====================

// 404 error handler for unknown routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    message: `Route ${req.method} ${req.originalUrl} not found`
  });
});

// Generic error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Different handling for development vs production
  const isProduction = process.env.NODE_ENV === 'production';

  // Sanitize error message in production
  const errorMessage = isProduction ? 'Internal server error' : err.message;
  const errorStack = isProduction ? undefined : err.stack;

  // Handle specific error types
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation Error',
      message: err.message
    });
  }

  if (err.name === 'CastError') {
    return res.status(400).json({
      error: 'Invalid ID format',
      message: 'The provided ID is not valid'
    });
  }

  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Authentication required'
    });
  }

  // Default error response
  res.status(err.statusCode || 500).json({
    error: err.name || 'InternalServerError',
    message: errorMessage,
    ...(errorStack && { stack: errorStack })
  });
});

// ====================
// START SERVER
// ====================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

